content:
Below is a focused Terraform implementation for the requested S3, RDS PostgreSQL, and Kubernetes service-account IAM role. It supports dev/prod with separate Terraform workspaces and environment-specific tfvars.

It assumes the VPC, private subnets, application security group, and EKS OIDC provider already exist.

## Repository layout

```text
terraform/
├── versions.tf
├── providers.tf
├── backend.tf
├── variables.tf
├── main.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    └── application-data/
        ├── versions.tf
        ├── variables.tf
        ├── s3.tf
        ├── rds.tf
        ├── iam.tf
        └── outputs.tf
```

---

## Root module

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

### `backend.tf`

Use an existing state bucket and locking table. Terraform workspaces automatically place non-default workspace states under separate workspace prefixes.

```hcl
terraform {
  backend "s3" {
    bucket         = "example-terraform-state"
    key            = "application-data/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "example-terraform-locks"
    encrypt        = true
  }
}
```

Production-grade state infrastructure should be created separately so destroying this stack cannot destroy its own state.

### `providers.tf`

```hcl
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Application = var.application_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

# Required by the child module even when replication is disabled.
provider "aws" {
  alias  = "replica"
  region = var.replica_region

  default_tags {
    tags = {
      Application = var.application_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}
```

### `variables.tf`

```hcl
variable "application_name" {
  description = "Application name used in resource names."
  type        = string
  default     = "webapp"
}

variable "environment" {
  description = "Deployment environment."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "aws_region" {
  description = "Primary AWS region."
  type        = string
}

variable "replica_region" {
  description = "Region used for the production S3 replica bucket."
  type        = string
  default     = "us-west-2"
}

variable "vpc_id" {
  description = "VPC in which RDS is deployed."
  type        = string
}

variable "database_subnet_ids" {
  description = "Private subnet IDs for the RDS subnet group."
  type        = list(string)

  validation {
    condition     = length(var.database_subnet_ids) >= 2
    error_message = "At least two database subnet IDs are required."
  }
}

variable "application_security_group_id" {
  description = "Security group allowed to connect to PostgreSQL."
  type        = string
}

variable "db_name" {
  description = "Initial PostgreSQL database name."
  type        = string
  default     = "app"
}

variable "db_username" {
  description = "PostgreSQL master username."
  type        = string
  default     = "app_admin"
}

variable "db_password" {
  description = "PostgreSQL master password. Supply through TF_VAR_db_password or an encrypted var file."
  type        = string
  sensitive   = true
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
}

variable "db_allocated_storage" {
  description = "Initial RDS storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Maximum storage autoscaling limit in GiB."
  type        = number
  default     = 100
}

variable "db_multi_az" {
  description = "Whether RDS should use a Multi-AZ deployment."
  type        = bool
}

variable "db_backup_retention_days" {
  description = "Number of days to retain RDS backups."
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "RDS backup retention must be at least 7 days."
  }
}

variable "eks_oidc_provider_arn" {
  description = "ARN of the EKS cluster IAM OIDC provider."
  type        = string
}

variable "eks_oidc_issuer_url" {
  description = "EKS OIDC issuer URL, for example https://oidc.eks.us-east-1.amazonaws.com/id/ABC."
  type        = string
}

variable "kubernetes_namespace" {
  description = "Namespace containing the Kubernetes service account."
  type        = string
  default     = "webapp"
}

variable "kubernetes_service_account" {
  description = "Name of the Kubernetes service account."
  type        = string
  default     = "webapp"
}
```

### `main.tf`

```hcl
locals {
  expected_workspace = var.environment
}

resource "terraform_data" "workspace_guard" {
  lifecycle {
    precondition {
      condition     = terraform.workspace == local.expected_workspace
      error_message = "Select the '${local.expected_workspace}' workspace before applying ${var.environment}.tfvars."
    }
  }
}

module "application_data" {
  source = "./modules/application-data"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  application_name             = var.application_name
  environment                  = var.environment
  enable_cross_region_replica  = var.environment == "prod"

  vpc_id                       = var.vpc_id
  database_subnet_ids          = var.database_subnet_ids
  application_security_group_id = var.application_security_group_id

  db_name                      = var.db_name
  db_username                  = var.db_username
  db_password                  = var.db_password
  db_instance_class            = var.db_instance_class
  db_allocated_storage         = var.db_allocated_storage
  db_max_allocated_storage     = var.db_max_allocated_storage
  db_multi_az                  = var.db_multi_az
  db_backup_retention_days     = var.db_backup_retention_days

  eks_oidc_provider_arn        = var.eks_oidc_provider_arn
  eks_oidc_issuer_url          = var.eks_oidc_issuer_url
  kubernetes_namespace         = var.kubernetes_namespace
  kubernetes_service_account   = var.kubernetes_service_account

  depends_on = [terraform_data.workspace_guard]
}
```

### `outputs.tf`

```hcl
output "assets_bucket_name" {
  value = module.application_data.assets_bucket_name
}

output "assets_bucket_arn" {
  value = module.application_data.assets_bucket_arn
}

output "replica_bucket_name" {
  value = module.application_data.replica_bucket_name
}

output "database_endpoint" {
  value = module.application_data.database_endpoint
}

output "database_port" {
  value = module.application_data.database_port
}

output "database_security_group_id" {
  value = module.application_data.database_security_group_id
}

output "service_account_role_arn" {
  value = module.application_data.service_account_role_arn
}
```

