## `modules/application-data/s3.tf`

```hcl
data "aws_caller_identity" "current" {}

locals {
  name_prefix = "${var.application_name}-${var.environment}"
  bucket_name = "${local.name_prefix}-assets-${data.aws_caller_identity.current.account_id}"

  replica_bucket_name = "${local.bucket_name}-replica"
}

resource "aws_s3_bucket" "assets" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "assets_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
      "s3:ListBucket"
    ]

    resources = [
      aws_s3_bucket.assets.arn,
      "${aws_s3_bucket.assets.arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "assets" {
  bucket = aws_s3_bucket.assets.id
  policy = data.aws_iam_policy_document.assets_bucket.json
}

resource "aws_s3_bucket" "replica" {
  count    = var.enable_cross_region_replica ? 1 : 0
  provider = aws.replica

  bucket = local.replica_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_cross_region_replica ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_cross_region_replica ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_cross_region_replica ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_cross_region_replica ? 1 : 0

  name               = "${local.name_prefix}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_cross_region_replica ? 1 : 0

  statement {
    sid = "ReadSourceVersioning"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadSourceVersions"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "WriteReplica"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]

    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_cross_region_replica ? 1 : 0

  name   = "${local.name_prefix}-s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_cross_region_replica ? 1 : 0

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.assets,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication
  ]
}
```

## `modules/application-data/rds.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${local.name_prefix}-postgres"
  subnet_ids = var.database_subnet_ids

  tags = {
    Name = "${local.name_prefix}-postgres"
  }
}

resource "aws_security_group" "database" {
  name_prefix = "${local.name_prefix}-postgres-"
  description = "Controls access to the ${local.name_prefix} PostgreSQL instance"
  vpc_id      = var.vpc_id

  ingress {
    description     = "PostgreSQL from application workloads"
    protocol        = "tcp"
    from_port       = 5432
    to_port         = 5432
    security_groups = [var.application_security_group_id]
  }

  # RDS does not normally initiate arbitrary outbound connections.
  egress = []

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_db_instance" "postgres" {
  identifier = "${local.name_prefix}-postgres"

  engine         = "postgres"
  engine_version = "16"

  instance_class        = var.db_instance_class
  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password
  port     = 5432

  multi_az            = var.db_multi_az
  publicly_accessible = false

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.database.id]

  backup_retention_period = var.db_backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-postgres-final"

  copy_tags_to_snapshot = true
  auto_minor_version_upgrade = true

  enabled_cloudwatch_logs_exports = [
    "postgresql",
    "upgrade"
  ]

  lifecycle {
    prevent_destroy = true
  }
}
```

## `modules/application-data/iam.tf`

This is an IRSA role with trust restricted to one namespace and one service account.

```hcl
locals {
  oidc_provider_host = trimsuffix(
    trimprefix(var.eks_oidc_issuer_url, "https://"),
    "/"
  )
}

data "aws_iam_policy_document" "service_account_assume_role" {
  statement {
    sid     = "AllowSpecificServiceAccount"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.eks_oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_provider_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_provider_host}:sub"
      values = [
        "system:serviceaccount:${var.kubernetes_namespace}:${var.kubernetes_service_account}"
      ]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name                 = "${local.name_prefix}-service-account"
  assume_role_policy   = data.aws_iam_policy_document.service_account_assume_role.json
  max_session_duration = 3600
}

data "aws_iam_policy_document" "service_account" {
  statement {
    sid = "ListAssetsBucket"

    actions = [
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadAndWriteApplicationAssets"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject"
    ]

    resources = [
      "${aws_s3_bucket.assets.arn}/application/*"
    ]
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${local.name_prefix}-application-assets"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account.json
}
```

The corresponding Kubernetes service account annotation is:

```yaml
apiVersion: v1
kind: ServiceAccount
metadata:
  name: webapp
  namespace: webapp
  annotations:
    eks.amazonaws.com/role-arn: arn:aws:iam::123456789012:role/webapp-prod-service-account
```

## `modules/application-data/outputs.tf`

```hcl
output "assets_bucket_name" {
  value = aws_s3_bucket.assets.id
}

output "assets_bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "replica_bucket_name" {
  value = try(aws_s3_bucket.replica[0].id, null)
}

output "database_endpoint" {
  description = "RDS hostname without embedding credentials."
  value       = aws_db_instance.postgres.address
}

output "database_port" {
  value = aws_db_instance.postgres.port
}

output "database_security_group_id" {
  value = aws_security_group.database.id
}

output "service_account_role_arn" {
  value = aws_iam_role.service_account.arn
}
```

